#!/bin/bash
LC="${HOME}/Desktop/logcollector.desktop"
LC_EXECUTABLE_PATH=`bash -ice "pyenv activate test_repo; pyenv which logcollector"`
LC_BIN_PATH=$(dirname "$LC_EXECUTABLE_PATH")
PYENV_PATH="$(cd "$(dirname "$LC_BIN_PATH")" && pwd)/"
COLLECTOR_IMAGE=`find ${PYENV_PATH} -name 'collector_128.png' -type f`

LC_BODY='[Desktop Entry]
Name=LogCollector
Comment=Most powerful log collector framework known to the world. Simple in use!
Exec=bash -ice "pyenv activate test_repo; logcollector qtgui;"
Icon='${COLLECTOR_IMAGE}'
Type=Application
Terminal=false
Categories=Accessories;
Encoding=UTF-8
Name[en_US]=LogCollector
StartupNotify=true
GenericName=Most powerful log collector framework known to the world. Simple in use!
Comment[en_US]=Most powerful log collector framework known to the world'
mkdir -p "${HOME}"/Desktop
echo -e "${LC_BODY}" > "${LC}"
chmod 755 "${LC}"
